class AsyncRuntimeTest(unittest.TestCase):
    def setUp(self) -> None:
        self.mock = MockServer()
        self.addCleanup(self.mock.close)
        self.sleeps: List[float] = []
        self.client = AsyncCore(api_key="st_live_runtime", base_url=self.mock.url)

        async def sleep(s: float) -> None:
            self.sleeps.append(s)

        self.client._sleep = sleep
        self.client._random = lambda: 0.0

    def test_retries_and_errors(self) -> None:
        self.mock.reply(error_reply(RETRYABLE), ok({"ok": True}), error_reply(FINAL))

        async def run() -> None:
            res = await self.client._get("/v1/test/item", {}, ident, None, None)
            self.assertEqual(res.data, {"ok": True})
            with self.assertRaises(ERROR_CLASSES[FINAL]):
                await self.client._get("/v1/test/item", {}, ident, None, None)

        asyncio.run(run())
        self.assertEqual(self.sleeps, [0.5])
        self.assertIsNotNone(self.mock.requests[1].param("max_age"))

    def test_iterate(self) -> None:
        more = {"has_more": True, "next_cursor": "c1.a", "next_cursor_expires_at": "2030-01-01T00:00:00Z"}
        self.mock.reply(*[Reply(200, {"data": [1], "page": more, "meta": META}, headers={HEADERS["credits_charged"]: "5"})] * 2)

        async def run() -> None:
            it = self.client._iterate("/v1/test/list", {}, ident, 5, 2, None, None, None)
            self.assertEqual(await it.to_list(), [1, 1])
            self.assertEqual((it.pages_fetched, it.credits_charged, it.stop_reason), (2, 10, "max_pages"))

        asyncio.run(run())


